const assert=require('node:assert/strict');const fs=require('fs');const {randomUUID}=require('crypto');const {PrismaClient}=require('@prisma/client');
const dbUrl=new URL(process.env.DATABASE_URL);dbUrl.searchParams.set('connection_limit','1');const p=new PrismaClient({datasourceUrl:dbUrl.toString()});const base=process.argv[2]||'http://127.0.0.1:4018';const origin=new URL(base).origin;const sessionId=randomUUID();
(async()=>{let checks=0;const ok=()=>checks++;const event={id:randomUUID(),name:'page_view',page:'home'};const batch={consent:true,sessionId,source:'direct',device:'mobile',events:[event]};const post=(body,headers={})=>fetch(base+'/api/store-analytics',{method:'POST',headers:{origin,'content-type':'application/json',...headers},body:typeof body==='string'?body:JSON.stringify(body)});
try{
assert.equal((await fetch(base+'/admin/analitica',{redirect:'manual'})).status,307);ok();
assert.equal((await post(batch,{origin:'https://wrong.example'})).status,403);ok();
assert.equal((await post('{')).status,400);ok();
assert.equal((await post({...batch,consent:false})).status,400);ok();
assert.equal((await post({...batch,email:'private@example.com'})).status,400);ok();
assert.equal((await post(batch)).status,204);assert.equal((await post(batch)).status,204);assert.equal(await p.storeAnalyticsEvent.count({where:{sessionId}}),1);ok();
assert.equal((await post({...batch,events:[{id:randomUUID(),name:'quote_created',page:'home',quoteId:'nonexistent-analytics-qa'}]})).status,204);assert.equal(await p.storeAnalyticsEvent.count({where:{sessionId,name:'quote_created'}}),0);ok();
await post({...batch,events:[{id:randomUUID(),name:'search_results',page:'home',searchTerm:'private@example.com',resultCount:0}]});const row=await p.storeAnalyticsEvent.findFirst({where:{sessionId,name:'search_results'}});assert.equal(row.searchTerm,null);ok();
const product=await p.product.findFirst({select:{code:true}});await p.storeAnalyticsEvent.createMany({data:[{id:randomUUID(),sessionId,name:'add_to_cart',page:'home',source:'direct',device:'mobile',productCode:product.code,createdAt:new Date(Date.now()-3600000)},{id:randomUUID(),sessionId,name:'search_results',page:'home',source:'direct',device:'mobile',searchTerm:'qa-analitica-temporal',resultCount:0}]});
const admin=await p.user.findFirst({where:{role:'ADMIN'},select:{id:true,email:true,name:true}});assert.ok(admin);const {SignJWT}=await import('jose');const token=await new SignJWT({userId:admin.id,email:admin.email,name:admin.name,role:'ADMIN',requirePasswordChange:false}).setProtectedHeader({alg:'HS256'}).setIssuedAt().setExpirationTime('5m').sign(new TextEncoder().encode(process.env.AUTH_SECRET));const headers={cookie:'importadora_session='+token};
for(const days of [1,7,30]){const response=await fetch(base+'/admin/analitica?days='+days,{headers});const html=await response.text();assert.equal(response.status,200);if(!html.includes('qa-analitica-temporal')) { fs.writeFileSync('analytics-debug.html',html,{mode:0o600}); console.log({days,unavailable:html.includes('Medición temporalmente no disponible'),password:html.includes('contraseña'),dashboard:html.includes('Del catálogo a la cotización')}); } assert.ok(html.includes('qa-analitica-temporal'));assert.ok(html.includes('Productos que despiertan'));assert.ok(!html.includes('Medición temporalmente no disponible'));ok();}
await p.storeAnalyticsEvent.deleteMany({where:{sessionId}});assert.equal(await p.storeAnalyticsEvent.count({where:{sessionId}}),0);ok();
const html=await(await fetch(base+'/admin/analitica?days=7',{headers})).text();fs.writeFileSync('analytics-preview.html',html,{mode:0o600});console.log(JSON.stringify({checks,syntheticEventsRemoved:true,adminDashboard:'ok',base}));
}finally{await p.storeAnalyticsEvent.deleteMany({where:{sessionId}});await p.$disconnect();}
})().catch(e=>{console.error(e.message);process.exitCode=1});

const fs=require('fs');const p='src/lib/catalog-pdf.ts';let s=fs.readFileSync(p,'utf8');
s=s.replace('all-catalogs-two-products-v7','all-catalogs-mobile-borderless-v8');
const a=s.indexOf('export function renderScopedCatalogPdf(');const b=s.indexOf('\nasync function createScopedCatalogPdf',a);
s=s.slice(0,a)+`export function renderScopedCatalogPdf(items: { image: Buffer | null; name: string; code: string; brand: string }[], title: string) {
  return new Promise<Buffer>((resolve, reject) => {
    // A long portrait sheet keeps two products while giving each the full phone width.
    const pageWidth = 595.28;
    const pageHeight = 1683.78;
    const doc = new PDFDocument({ autoFirstPage: false, compress: true, size: [pageWidth, pageHeight], margin: 0,
      info: { Title: title, Author: "Importaciones Super", Subject: title } });
    const chunks: Buffer[] = [];
    doc.on("data", (chunk: Buffer) => chunks.push(chunk));
    doc.on("error", reject);
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    const productsPerPage = 2;
    const margin = 18;
    const headerHeight = 72;
    const gap = 28;
    const contentWidth = pageWidth - margin * 2;
    const productHeight = (pageHeight - headerHeight - 26 - gap) / productsPerPage;
    const imageHeight = productHeight - 64;
    const pages = Math.ceil(items.length / productsPerPage);
    for (let page = 0; page < pages; page++) {
      doc.addPage();
      doc.fillColor(BRAND_PRIMARY).font("Helvetica-Bold").fontSize(18);
      let titleSize = 18;
      while (doc.heightOfString(title, { width: contentWidth }) > 32 && titleSize > 10) doc.fontSize(--titleSize);
      doc.text(title, margin, 12, { width: contentWidth, height: 32, ellipsis: true, align: "center" });
      doc.fillColor("#666666").font("Helvetica").fontSize(10)
        .text(\`Importaciones Super | \${items.length} productos\`, margin, 48, { width: contentWidth, align: "center" });
      for (let slot = 0; slot < productsPerPage; slot++) {
        const item = items[page * productsPerPage + slot];
        if (!item) break;
        const y = headerHeight + slot * (productHeight + gap);
        if (item.image) doc.image(item.image, margin, y, { fit: [contentWidth, imageHeight], align: "center", valign: "center" });
        else doc.fillColor("#777777").font("Helvetica").fontSize(14)
          .text("Imagen no disponible", margin, y + imageHeight / 2, { width: contentWidth, align: "center" });
        doc.fillColor("#17172B").font("Helvetica-Bold").fontSize(14);
        let size = 14;
        while (doc.heightOfString(item.name, { width: contentWidth }) > 34 && size > 11) doc.fontSize(--size);
        doc.text(item.name, margin, y + imageHeight + 8, { width: contentWidth, height: 34, ellipsis: true, align: "center" });
        doc.fillColor(BRAND_PRIMARY).font("Helvetica").fontSize(12)
          .text(\`Código: \${item.code}\`, margin, y + imageHeight + 46, { width: contentWidth, height: 18, ellipsis: true, align: "center" });
      }
      doc.fillColor("#666666").font("Helvetica").fontSize(10)
        .text(\`\${page + 1} / \${pages}\`, margin, pageHeight - 16, { width: contentWidth, align: "center" });
    }
    doc.end();
  });
}
`.replaceAll('\\`','`').replaceAll('\\$','$')+s.slice(b);
