            assignedToName={quote.assignedToName}
            assignedToEmail={quote.assignedToEmail}
            customerName={quote.customerName}
            customerPhone={quote.customerPhone ?? ""}
            customerMessage={quote.note}
            pdfLink={pdfLink}
            quoteNumber={quote.quoteNumber}
          />
        </div>

      </div>
    </section>
  );
}

