import { writeFileSync } from 'node:fs';
import { prisma } from '../../src/lib/prisma';
import { RockyAIOrchestrator } from '../../src/lib/rocky/orchestrator';
import { createToolBackend } from '../../src/lib/rocky/backend';
import { PostgresKnowledge } from '../../src/lib/rocky/rag';
import { memorySchema } from '../../src/lib/rocky/contracts';
import { redactSensitiveText } from '../../src/lib/rocky/guardrails';

async function main() {
 const end=new Date(),start=new Date(end.getTime()-86400000);
 const inbound=await prisma.chatMessage.findMany({where:{createdAt:{gte:start,lte:end},direction:'INBOUND'},select:{id:true,conversationId:true,conversation:{select:{contact:{select:{externalId:true}}}}}});
 const real=inbound.filter(m=>!m.conversation.contact.externalId?.startsWith('SIMULATOR:'));
 const ids=[...new Set(real.map(m=>m.conversationId))];
 const targetIds=new Set(real.map(m=>m.id));
 const products=await prisma.product.findMany({where:{isVisible:true},select:{code:true,slug:true,name:true}});
 const known=new Set(products.map(p=>p.code.toUpperCase()));
 const backend=createToolBackend(new PostgresKnowledge(),{catalogPdf:false});
 // Cache read results for a single audit; no PDFs, model calls, writes or customer messages.
 for(const key of ['search','product','knowledge','business','catalog'] as const) {
  const fn=backend[key]; if(!fn) continue; const cache=new Map<string,unknown>();
  (backend as any)[key]=async(...args:any[])=>{const k=JSON.stringify(args);if(!cache.has(k)) cache.set(k,await (fn as any).apply(backend,args));return cache.get(k)};
 }
 const engine=new RockyAIOrchestrator(backend);
 const clean=(s:string)=>redactSensitiveText(s).replace(/data:[^\s]+/g,'[adjunto]').replace(/\b\d{7,}\b/g,'[número]').replace(/[\w.+-]+@[\w.-]+\.[a-z]{2,}/gi,'[correo]').slice(0,1600);
 const rows:any[]=[];
 for(let ci=0;ci<ids.length;ci++) {
  const conversationId=ids[ci];
  const before=await prisma.chatMessage.findMany({where:{conversationId,createdAt:{lt:start}},orderBy:{createdAt:'desc'},take:6,select:{id:true,createdAt:true,direction:true,messageType:true,content:true}});
  const within=await prisma.chatMessage.findMany({where:{conversationId,createdAt:{gte:start,lte:end}},orderBy:[{createdAt:'asc'},{id:'asc'}],select:{id:true,createdAt:true,direction:true,messageType:true,content:true}});
  let memory=memorySchema.parse({});let context:string[]=[];
  for(const m of [...before.reverse(),...within]) {
   const text=m.content;
   if(m.direction==='OUTBOUND' || !targetIds.has(m.id)) {
    const codes=[...new Set((text.toUpperCase().match(/\b[A-Z0-9][A-Z0-9-]{1,30}\b/g)||[]).filter(c=>known.has(c)))].slice(0,6);
    if(codes.length){memory.shownCodes=codes;if(codes.length===1)memory.productCodes=codes;}
    context.push(`${m.direction}: ${clean(text)}`); context=context.slice(-4);continue;
   }
   const row:any={n:rows.length+1,c:ci+1,id:m.id,at:m.createdAt,type:m.messageType,text:clean(text),context:[...context],memoryCodes:memory.productCodes};
   if(m.messageType==='TEXT') {
    try {
     const r=await engine.chat({text:redactSensitiveText(text).slice(0,1200),memory});
     row.intent=r.intent;row.human=r.requiresHuman;row.reason=r.reasonCode;row.reply=r.reply;
     row.products=r.products.map(p=>({code:p.code,name:p.name,stock:p.stockUnits,price:p.unitPrice,specs:!!p.technicalSpecs}));
     row.sources=r.sources.map(s=>({type:s.sourceType,title:s.title,text:s.text.slice(0,400)}));
     row.catalog=r.catalog;memory=r.memory;
    }catch(e){row.error=String(e)}
   }
   rows.push(row);context.push(`INBOUND: ${clean(text)}`);context=context.slice(-4);
  }
  if((ci+1)%50===0)console.error(`Audited ${ci+1}/${ids.length} conversations`);
 }
 writeFileSync('/tmp/rocky-inbox-audit-current.json',JSON.stringify({start,end,realInbound:real.length,conversations:ids.length,method:'Read-only deterministic replay, no LLM/vision/vector/PDF; original preceding context only; current catalog',rows}));
 console.log(JSON.stringify({ok:true,rows:rows.length,conversations:ids.length}));
}
main().catch(e=>{console.error(e);process.exitCode=1}).finally(()=>prisma.$disconnect());

