const fs = require('node:fs');
const vm = require('node:vm');
const net = require('node:net');
const {execFileSync} = require('node:child_process');
const {Client} = require('ssh2');
const match = fs.readFileSync('check-logs-vps.js','utf8').match(/const sshConfig = (\{[\s\S]*?\});/);
const config = vm.runInNewContext(`(${match[1]})`);
const known = execFileSync('ssh-keygen',['-F',config.host],{encoding:'utf8'}).split(/\r?\n/).filter(l=>l&&!l.startsWith('#')).map(l=>l.trim().split(/\s+/)[2]);
if(!known.length) throw new Error('Known host required');
const client = new Client();
const server = net.createServer(socket=>{
 client.forwardOut('127.0.0.1',socket.remotePort||0,'127.0.0.1',4113,(error,stream)=>{
  if(error){socket.destroy();return;}
  socket.pipe(stream).pipe(socket);
  socket.on('error',()=>stream.destroy());
  stream.on('error',()=>socket.destroy());
 });
});
client.on('ready',()=>server.listen(3113,'127.0.0.1',()=>console.log('Private preview tunnel ready on 127.0.0.1:3113')));
client.on('error',e=>{console.error(e.message);server.close();});
client.connect({...config,readyTimeout:30000,keepaliveInterval:15000,hostVerifier:key=>known.includes(key.toString('base64'))});
process.on('SIGINT',()=>{server.close();client.end();process.exit(0);});

