export async function saveDigitalProfileAction(formData: FormData) {
  await requireAdmin();
  const productId = String(formData.get("productId") ?? "");
  if (!productId) {
    redirect("/admin/fichas?status=error&error=No se especificó el producto.");
  }

  const descriptionShort = String(formData.get("descriptionShort") ?? "").trim();
  const descriptionFull = String(formData.get("descriptionFull") ?? "").trim();
  const status = String(formData.get("status") ?? "BORRADOR").trim();

  const specsStr = String(formData.get("specifications") ?? "[]");
  const variantsStr = String(formData.get("variants") ?? "[]");
  const videosStr = String(formData.get("videos") ?? "[]");
  const docsStr = String(formData.get("documents") ?? "[]");

  const specs = JSON.parse(specsStr);
  const variants = JSON.parse(variantsStr);
  const videos = JSON.parse(videosStr);
  const docs = JSON.parse(docsStr);

  await prisma.$transaction(async (tx) => {
    // 1. DigitalProductProfile
    await tx.digitalProductProfile.upsert({
      where: { productId },
      create: {
        productId,
        descriptionShort,
        descriptionFull,
        status,
      },
      update: {
        descriptionShort,
        descriptionFull,
        status,
      },
    });

    // 2. Specifications
    await tx.productSpecification.deleteMany({ where: { productId } });
    if (specs.length > 0) {
      await tx.productSpecification.createMany({
        data: specs.map((s: any, idx: number) => ({
          productId,
          name: s.name,
          value: s.value,
          sortOrder: s.sortOrder ?? idx,
        })),
      });
    }

    // 3. Variants
    await tx.productVariant.deleteMany({ where: { productId } });
    if (variants.length > 0) {
      await tx.productVariant.createMany({
        data: variants.map((v: any, idx: number) => ({
          productId,
          name: v.name,
          hexColor: v.hexColor || null,
          imageUrl: v.imageUrl || null,
          sku: v.sku || null,
          isAvailable: v.isAvailable !== false,
          sortOrder: v.sortOrder ?? idx,
        })),
      });
    }

    // 4. Videos
    await tx.productVideo.deleteMany({ where: { productId } });
    if (videos.length > 0) {
      await tx.productVideo.createMany({
        data: videos.map((v: any, idx: number) => ({
          productId,
          title: v.title,
          url: v.url,
          provider: v.provider,
          videoId: v.videoId,
          thumbnailUrl: v.thumbnailUrl || null,
          sortOrder: v.sortOrder ?? idx,
        })),
      });
    }

    // 5. Documents
    await tx.productDocument.deleteMany({ where: { productId } });
    if (docs.length > 0) {
      await tx.productDocument.createMany({
        data: docs.map((d: any, idx: number) => ({
          productId,
          title: d.title,
          url: d.url,
          type: d.type,
          sortOrder: d.sortOrder ?? idx,
        })),
      });
    }
  });

  revalidatePath("/admin/fichas");
  revalidatePath(`/admin/fichas/${productId}`);
  redirect(`/admin/fichas/${productId}?status=updated`);
}

export async function generateQrAction(formData: FormData) {
  await requireAdmin();
  const productId = String(formData.get("productId") ?? "");
  if (!productId) {
    redirect("/admin/fichas?status=error&error=No se especificó el producto.");
  }

  const product = await prisma.product.findUnique({
    where: { id: productId },
    select: { slug: true },
  });

  if (!product) {
    redirect("/admin/fichas?status=error&error=No se encontró el producto.");
  }

  const siteUrl = process.env.NEXT_PUBLIC_SITE_URL || "https://tiendavirtualsuper.com";
  const destUrl = `${siteUrl}/p/${product.slug}`;

  const qrDataUrl = await QRCode.toDataURL(destUrl, {
    width: 400,
    margin: 2,
    errorCorrectionLevel: "H",
  });

  await prisma.productQr.upsert({
    where: { productId },
    create: {
      productId,
      destUrl,
      imageUrl: qrDataUrl,
    },
    update: {
      destUrl,
      imageUrl: qrDataUrl,
    },
  });

  revalidatePath("/admin/fichas");
  revalidatePath(`/admin/fichas/${productId}`);
  redirect(`/admin/fichas/${productId}?status=qr_generated`);
}

