        <DeleteRecordButton recordId={quote.id} recordType="quote" userEmail={session?.email ?? ""} onDelete={deleteQuoteAction} />
        {customerWhatsappHref ? (
          <a
            className="button button-primary"
            href={customerWhatsappHref}
            rel="noreferrer"
            target="_blank"
          >
            <MessageCircle size={16} />
            Contactar cliente
          </a>
        ) : null}
      </div>

      <section className="panel admin-quote-detail-hero">
        <div>
          <p className="eyebrow">Cotización</p>
          <h1>{quote.quoteNumber ?? "Sin número ERP"}</h1>
