                      <td data-label="Cantidad">{item.quantity}</td>
                      <td data-label="Total">
                        <strong>{formatCurrency(item.total, quote.currencySymbol)}</strong>
                      </td>
                      <td data-label="Acciones">
                        {item.productId ? (
                          <Link className="icon-button" href={`/admin/products/${item.productId}`}>
