                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          {/* Timeline and error notifications */}
          {(quote.errorMessage || timeline.length > 0) && (
            <div className="admin-quote-detail-grid" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: "24px" }}>
              {quote.errorMessage && (
