"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { MessageCircle, TriangleAlert, X } from "lucide-react";
import { ChatHeader } from "./ChatHeader";
import { ConversationList, type ConversationFilters } from "./ConversationList";
import { CustomerPanel } from "./CustomerPanel";
import { MessageBubble } from "./MessageBubble";
import { MessageInput } from "./MessageInput";
import type { ChatMessage, Conversation, MessageType } from "@/types/messages";
import { templateSelectionSchema, type TemplateSelection } from "@/lib/message-templates";

const CONVERSATION_PAGE_SIZE = 30;
const MESSAGE_PAGE_SIZE = 60;
const CONVERSATION_POLL_MS = 10000;
const MESSAGE_POLL_MS = 5000;

const DEFAULT_FILTERS: ConversationFilters = {
  dateFrom: "",
  dateTo: "",
  phone: "",
  q: "",
  search: "",
  status: "",
  unreadOnly: false,
};

type ConversationsResponse = {
  hasMore: boolean;
  items: Conversation[];
  page: number;
  total: number;
  totalPages: number;
};

type MessagesResponse = {
  hasMore: boolean;
  items: ChatMessage[];
  latestId: string | null;
  latestAt: string | null;
  nextBeforeId: string | null;
  nextBefore: string | null;
  total: number;
};

type RockySuggestion = { runId: string; triggerMessageId: string; reply: string };

function useDebouncedValue<T>(value: T, delayMs: number) {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const timeout = window.setTimeout(() => setDebouncedValue(value), delayMs);
    return () => window.clearTimeout(timeout);
  }, [delayMs, value]);

  return debouncedValue;
}

function appendParam(params: URLSearchParams, key: string, value: string | boolean | undefined) {
  if (typeof value === "boolean") {
    if (value) {
      params.set(key, "true");
    }
    return;
  }

  if (value?.trim()) {
    params.set(key, value.trim());
  }
}

function buildConversationParams(filters: ConversationFilters, page: number) {
  const params = new URLSearchParams({
    limit: String(CONVERSATION_PAGE_SIZE),
    page: String(page),
    t: String(Date.now()),
  });

  appendParam(params, "search", filters.search);
  appendParam(params, "phone", filters.phone);
  appendParam(params, "q", filters.q);
  appendParam(params, "dateFrom", filters.dateFrom);
  appendParam(params, "dateTo", filters.dateTo);
  appendParam(params, "status", filters.status || undefined);
  appendParam(params, "unreadOnly", filters.unreadOnly);

  return params;
}

function buildMessageParams(
  filters: ConversationFilters,
  extra?: { after?: string; afterId?: string; before?: string; beforeId?: string },
) {
  const params = new URLSearchParams({
    limit: String(MESSAGE_PAGE_SIZE),
    t: String(Date.now()),
  });

  appendParam(params, "q", filters.q);
  appendParam(params, "dateFrom", filters.dateFrom);
  appendParam(params, "dateTo", filters.dateTo);
  appendParam(params, "before", extra?.before);
  appendParam(params, "beforeId", extra?.beforeId);
  appendParam(params, "after", extra?.after);
  appendParam(params, "afterId", extra?.afterId);

  return params;
}

async function fetchConversationsPage(
  filters: ConversationFilters,
  page: number,
  signal?: AbortSignal,
) {
  const params = buildConversationParams(filters, page);
  const response = await fetch(`/api/admin/conversations?${params.toString()}`, {
    cache: "no-store",
    signal,
  });

  if (!response.ok) {
    throw new Error("No se pudieron cargar las conversaciones.");
  }

  return (await response.json()) as ConversationsResponse;
}

async function fetchMessagesPage(
  conversationId: string,
  filters: ConversationFilters,
  extra?: { after?: string; afterId?: string; before?: string; beforeId?: string },
  signal?: AbortSignal,
) {
  const params = buildMessageParams(filters, extra);
  const response = await fetch(`/api/admin/conversations/${conversationId}/messages?${params.toString()}`, {
    cache: "no-store",
    signal,
  });

  if (!response.ok) {
    throw new Error("No se pudieron cargar los mensajes.");
  }

  return (await response.json()) as MessagesResponse;
}

function sortConversations(conversations: Conversation[]) {
  return [...conversations].sort(
    (a, b) => new Date(b.lastMessageAt).getTime() - new Date(a.lastMessageAt).getTime(),
  );
}

function mergeConversations(base: Conversation[], incoming: Conversation[]) {
  const byId = new Map<string, Conversation>();

  for (const conversation of base) {
    byId.set(conversation.id, conversation);
  }

  for (const conversation of incoming) {
    byId.set(conversation.id, conversation);
  }

  return sortConversations([...byId.values()]);
}

function mergeMessages(base: ChatMessage[], incoming: ChatMessage[]) {
  const byId = new Map<string, ChatMessage>();

  for (const message of base) {
    byId.set(message.id, message);
  }

  for (const message of incoming) {
    byId.set(message.id, message);
  }

  return [...byId.values()].sort(
    (a, b) =>
      new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime() ||
      a.id.localeCompare(b.id),
  );
}

function isNearBottom(element: HTMLDivElement | null) {
  if (!element) {
    return true;
  }

  return element.scrollHeight - element.scrollTop - element.clientHeight < 120;
}

function asMessageType(value: string): MessageType {
  const allowedTypes: MessageType[] = ["TEXT", "IMAGE", "VIDEO", "DOCUMENT", "AUDIO", "LOCATION", "CONTACT", "UNKNOWN"];
  return allowedTypes.includes(value as MessageType) ? (value as MessageType) : "TEXT";
}

export function MessagesWorkspace() {
  const [filters, setFilters] = useState<ConversationFilters>(DEFAULT_FILTERS);
  const debouncedFilters = useDebouncedValue(filters, 350);
  const messageFilters = useMemo(
    () => ({
      ...DEFAULT_FILTERS,
    }),
    [],
  );

  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [conversationPage, setConversationPage] = useState(1);
  const [conversationTotal, setConversationTotal] = useState(0);
  const [conversationHasMore, setConversationHasMore] = useState(false);
  const [activeMessages, setActiveMessages] = useState<ChatMessage[]>([]);
  const [activeId, setActiveId] = useState<string | undefined>();
  const activeIdRef = useRef<string | undefined>(undefined);
  const [messageTotal, setMessageTotal] = useState(0);
  const [messageHasMore, setMessageHasMore] = useState(false);
  const [loadingConversations, setLoadingConversations] = useState(true);
  const [loadingMoreConversations, setLoadingMoreConversations] = useState(false);
  const [loadingMessages, setLoadingMessages] = useState(false);
  const [loadingOlderMessages, setLoadingOlderMessages] = useState(false);
  const [refreshNonce, setRefreshNonce] = useState(0);
  const [workspaceError, setWorkspaceError] = useState<string | null>(null);
  const [rockySuggestion, setRockySuggestion] = useState<RockySuggestion | null>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const activeMessagesRef = useRef<ChatMessage[]>([]);
  const conversationsRef = useRef<Conversation[]>([]);

  const activeConversation = conversations.find((conversation) => conversation.id === activeId);
  useEffect(() => { activeIdRef.current = activeId; }, [activeId]);
  const debouncedConversationKey = useMemo(() => JSON.stringify(debouncedFilters), [debouncedFilters]);

  const scrollToBottom = useCallback((behavior: ScrollBehavior = "auto") => {
    messagesEndRef.current?.scrollIntoView({ behavior, block: "end" });
  }, []);

  useEffect(() => {
    activeMessagesRef.current = activeMessages;
  }, [activeMessages]);

  useEffect(() => {
    conversationsRef.current = conversations;
  }, [conversations]);

  useEffect(() => {
    if (!activeId) { setRockySuggestion(null); return undefined; }
    let stopped = false;
    const refreshSuggestion = async () => {
      try {
        const response = await fetch(`/api/admin/rocky?conversationId=${encodeURIComponent(activeId)}`, { cache: "no-store" });
        if (!response.ok || stopped) return;
        const payload = await response.json() as { runs?: Array<{ id: string; triggerMessageId: string; result?: { reply?: string; finalAction?: string } }> };
        const lastInbound = [...activeMessagesRef.current].reverse().find(message => message.direction === "INBOUND" && message.senderType === "CUSTOMER");
        const run = payload.runs?.find(item => item.triggerMessageId === lastInbound?.id && item.result?.finalAction === "SUGGEST" && item.result.reply);
        setRockySuggestion(run ? { runId: run.id, triggerMessageId: run.triggerMessageId, reply: run.result!.reply! } : null);
      } catch { /* Polling de sugerencias no debe bloquear la bandeja. */ }
    };
    void refreshSuggestion();
    const interval = window.setInterval(refreshSuggestion, MESSAGE_POLL_MS);
    return () => { stopped = true; window.clearInterval(interval); };
  }, [activeId]);

  useEffect(() => {
    const controller = new AbortController();
    const filtersSnapshot = debouncedFilters;

    const loadInitialConversations = async () => {
      setLoadingConversations(true);
      setConversationPage(1);

      try {
        const data = await fetchConversationsPage(filtersSnapshot, 1, controller.signal);
        setWorkspaceError(null);
        setConversations(data.items);
        setConversationTotal(data.total);
        setConversationHasMore(data.hasMore);
      } catch (error) {
        if (!controller.signal.aborted) {
          console.error("Failed to fetch conversations", error);
          setWorkspaceError(error instanceof Error ? error.message : "No se pudieron cargar las conversaciones.");
        }
      } finally {
        if (!controller.signal.aborted) {
          setLoadingConversations(false);
        }
      }
    };

    loadInitialConversations();

    const interval = window.setInterval(async () => {
      try {
        const data = await fetchConversationsPage(filtersSnapshot, 1);
        const merged = mergeConversations(conversationsRef.current, data.items);
        setConversations(merged);
        setConversationTotal(data.total);
        setConversationHasMore(data.total > merged.length);
      } catch (error) {
        console.error("Failed to refresh conversations", error);
      }
    }, CONVERSATION_POLL_MS);

    return () => {
      controller.abort();
      window.clearInterval(interval);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [debouncedConversationKey, refreshNonce]);

  useEffect(() => {
    if (!activeId) {
      return undefined;
    }

    const controller = new AbortController();
    const filtersSnapshot = messageFilters;

    const loadInitialMessages = async () => {
      setLoadingMessages(true);

      try {
        const data = await fetchMessagesPage(activeId, filtersSnapshot, undefined, controller.signal);
        setWorkspaceError(null);
        setActiveMessages(data.items);
        setMessageTotal(data.total);
        setMessageHasMore(data.hasMore);
        window.requestAnimationFrame(() => scrollToBottom("auto"));
      } catch (error) {
        if (!controller.signal.aborted) {
          console.error("Failed to fetch messages", error);
          setWorkspaceError(error instanceof Error ? error.message : "No se pudieron cargar los mensajes.");
        }
      } finally {
        if (!controller.signal.aborted) {
          setLoadingMessages(false);
        }
      }
    };

    loadInitialMessages();

    return () => controller.abort();
  }, [activeId, messageFilters, scrollToBottom]);

  useEffect(() => {
    if (!activeId) {
      return undefined;
    }

    const filtersSnapshot = messageFilters;
    const controller = new AbortController();
    let polling = false;
    const interval = window.setInterval(async () => {
      if (polling) return;
      const latestMessage = activeMessagesRef.current.at(-1);

      if (!latestMessage) {
        return;
      }

      try {
        polling = true;
        const data = await fetchMessagesPage(activeId, filtersSnapshot, {
          afterId: latestMessage.id,
          after: new Date(latestMessage.createdAt).toISOString(),
        }, controller.signal);
        const ids = activeMessagesRef.current.filter(m => m.direction === "OUTBOUND").slice(-200).map(m => m.id);
        const statusResponse = await fetch("/api/admin/messages/statuses", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ conversationId: activeId, ids }), signal: controller.signal,
        });
        if (!statusResponse.ok) throw new Error("No se pudieron actualizar los estados.");
        const statusData = await statusResponse.json() as { items: Array<Pick<ChatMessage, "id" | "status" | "metadata" | "externalMessageId">> };
        if (controller.signal.aborted) return;
        const updates = new Map(statusData.items.map(m => [m.id, m]));
        setActiveMessages(current => current.map(m => updates.has(m.id) ? { ...m, ...updates.get(m.id)! } : m));

        const knownIds = new Set(activeMessagesRef.current.map((message) => message.id));
        const newItems = data.items.filter((message) => !knownIds.has(message.id));

        if (!newItems.length) {
          return;
        }

        const shouldScroll = isNearBottom(messagesContainerRef.current);
        setActiveMessages((current) => mergeMessages(current, newItems));
        setMessageTotal(data.total);

        if (shouldScroll) {
          window.requestAnimationFrame(() => scrollToBottom("smooth"));
        }
      } catch (error) {
        if (!controller.signal.aborted) console.error("Failed to poll messages", error);
      } finally {
        polling = false;
      }
    }, MESSAGE_POLL_MS);

    return () => { controller.abort(); window.clearInterval(interval); };
  }, [activeId, messageFilters, scrollToBottom]);

  const handleFiltersChange = useCallback((nextFilters: Partial<ConversationFilters>) => {
    setFilters((current) => ({ ...current, ...nextFilters }));
  }, []);

  const handleLoadMoreConversations = useCallback(async () => {
    if (loadingConversations || loadingMoreConversations || !conversationHasMore) {
      return;
    }

    const nextPage = conversationPage + 1;
    setLoadingMoreConversations(true);

    try {
      const data = await fetchConversationsPage(debouncedFilters, nextPage);
      setConversations((current) => mergeConversations(current, data.items));
      setConversationPage(nextPage);
      setConversationTotal(data.total);
      setConversationHasMore(data.hasMore);
    } catch (error) {
      console.error("Failed to load more conversations", error);
    } finally {
      setLoadingMoreConversations(false);
    }
  }, [
    conversationHasMore,
    conversationPage,
    debouncedFilters,
    loadingConversations,
    loadingMoreConversations,
  ]);

  const handleLoadOlderMessages = useCallback(async () => {
    if (!activeId || loadingMessages || loadingOlderMessages || !messageHasMore) {
      return;
    }

    const oldestMessage = activeMessagesRef.current[0];

    if (!oldestMessage) {
      return;
    }

    const container = messagesContainerRef.current;
    const previousHeight = container?.scrollHeight ?? 0;
    const previousTop = container?.scrollTop ?? 0;
    setLoadingOlderMessages(true);

    try {
      const data = await fetchMessagesPage(activeId, messageFilters, {
        beforeId: oldestMessage.id,
        before: new Date(oldestMessage.createdAt).toISOString(),
      });

      setActiveMessages((current) => mergeMessages(data.items, current));
      setMessageTotal(data.total);
      setMessageHasMore(data.hasMore);

      window.requestAnimationFrame(() => {
        if (!container) {
          return;
        }

        container.scrollTop = container.scrollHeight - previousHeight + previousTop;
      });
    } catch (error) {
      console.error("Failed to load older messages", error);
    } finally {
      setLoadingOlderMessages(false);
    }
  }, [activeId, loadingMessages, loadingOlderMessages, messageFilters, messageHasMore]);

  const handleMessagesScroll = useCallback(() => {
    const container = messagesContainerRef.current;

    if (container && container.scrollTop < 120) {
      void handleLoadOlderMessages();
    }
  }, [handleLoadOlderMessages]);

  const handleSelectConversation = (id: string) => {
    setActiveId(id);
    setConversations((current) =>
      current.map((conversation) =>
        conversation.id === id ? { ...conversation, unreadCount: 0 } : conversation,
      ),
    );
    setActiveMessages([]);
    setMessageTotal(0);
    setMessageHasMore(false);
  };

  const handleBackToConversations = () => {
    setActiveId(undefined);
    setActiveMessages([]);
    setMessageTotal(0);
    setMessageHasMore(false);
  };

  const handleSendMessage = async (content: string, mediaUrl?: string, type: string = "TEXT", template?: TemplateSelection): Promise<boolean> => {
    if (!activeId || activeIdRef.current !== activeId) {
      return false;
    }

    const now = new Date();
    const requestId = crypto.randomUUID();
    const messageType = asMessageType(type);
    const tempMessage: ChatMessage = {
      content,
      conversationId: activeId,
      createdAt: now,
      direction: "OUTBOUND",
      externalMessageId: null,
      id: `m-new-${now.getTime()}`,
      mediaUrl: mediaUrl || null,
      messageType,
      metadata: { requestId, ...(template ? { template } : {}) },
      senderType: "AGENT",
      status: "sending",
    };

    setActiveMessages((current) => [...current, tempMessage]);
    setConversations((current) =>
      current.map((conversation) =>
        conversation.id === activeId
          ? {
              ...conversation,
              botEnabled: false,
              lastMessage: {
                content,
                createdAt: now,
                id: tempMessage.id,
                messageType,
                senderType: "AGENT",
              },
              lastMessageAt: now,
              status: conversation.status === "AUTOMATICO" ? "ATENDIENDO" : conversation.status,
            }
          : conversation,
      ),
    );
    window.requestAnimationFrame(() => scrollToBottom("smooth"));

    let persistedFailureId: string | undefined;
    try {
      const response = await fetch(`/api/admin/conversations/${activeId}/messages`, {
        body: JSON.stringify({ content, type, mediaUrl: mediaUrl || undefined, requestId, template }),
        headers: { "Content-Type": "application/json" },
        method: "POST",
      });

      if (!response.ok) {
        const payload = (await response.json().catch(() => null)) as { error?: string; messageId?: string } | null;
        if (typeof payload?.messageId === "string") persistedFailureId = payload.messageId;
        throw new Error(payload?.error || "No se pudo enviar el mensaje.");
      }

      const savedMessage = (await response.json()) as ChatMessage;
      setActiveMessages((current) =>
        activeIdRef.current !== activeId ? current : mergeMessages(
          current.filter((message) => message.id !== tempMessage.id),
          [savedMessage],
        ),
      );
      return true;
    } catch (error) {
      const reason = error instanceof Error ? error.message : "No se pudo enviar el mensaje.";
      console.error("Send error", { requestId, reason });
      setActiveMessages((current) =>
        activeIdRef.current !== activeId ? current : mergeMessages(
          current.filter(message => message.id !== tempMessage.id),
          [{ ...tempMessage, id: persistedFailureId || tempMessage.id, status: "failed", metadata: { requestId, error: reason, ...(template ? { template } : {}) } }],
        ),
      );
      return false;
    }
  };

  const handleToggleBot = async () => {
    await handleRockyModeChange(activeConversation?.botEnabled ? "MANUAL" : "COPILOT");
  };

  const handleRockyModeChange = async (mode: "MANUAL" | "COPILOT" | "AUTO") => {
    if (!activeId) return;
    const previous = activeConversation;
    setConversations(current => current.map(conversation => conversation.id === activeId ? {
      ...conversation, botEnabled: mode !== "MANUAL", status: mode === "MANUAL" ? "ATENDIENDO" : "AUTOMATICO",
      assignedUserId: mode === "MANUAL" ? conversation.assignedUserId : null, rockySession: { mode },
    } : conversation));
    try {
      const response = await fetch("/api/admin/rocky", { method: "POST", headers: { "content-type": "application/json" },
        body: JSON.stringify({ action: "mode", conversationId: activeId, mode }) });
      if (!response.ok) throw new Error("No se pudo cambiar el modo de Rocky.");
      if (mode !== "COPILOT") setRockySuggestion(null);
    } catch (error) {
      if (previous) setConversations(current => current.map(conversation => conversation.id === activeId ? previous : conversation));
      setWorkspaceError(error instanceof Error ? error.message : "No se pudo cambiar el modo de Rocky.");
    }
  };

  const handleTakeConversation = async () => {
    if (!activeId) {
      return;
    }

    setConversations((previous) =>
      previous.map((conversation) =>
        conversation.id === activeId
          ? {
              ...conversation,
              botEnabled: false,
              status: "ATENDIENDO",
            }
          : conversation,
      ),
    );

    await fetch("/api/admin/rocky", { method: "POST", headers: { "content-type": "application/json" },
      body: JSON.stringify({ action: "mode", conversationId: activeId, mode: "MANUAL" }) });
    setConversations(current => current.map(conversation => conversation.id === activeId
      ? { ...conversation, rockySession: { mode: "MANUAL" } } : conversation));
    setRockySuggestion(null);
  };

  const handleCloseConversation = async () => {
    if (!activeId) {
      return;
    }

    const conversationId = activeId;

    setConversations((previous) =>
      previous.map((conversation) =>
        conversation.id === conversationId ? { ...conversation, status: "CERRADO" } : conversation,
      ),
    );
    setActiveId(undefined);
    setActiveMessages([]);
    setMessageTotal(0);
    setMessageHasMore(false);

    await fetch(`/api/admin/conversations/${conversationId}`, {
      body: JSON.stringify({ status: "CERRADO" }),
      headers: { "Content-Type": "application/json" },
      method: "PATCH",
    });
  };

  return (
    <div className={`messages-workspace ${activeId ? "chat-open" : ""}`}>
      {workspaceError ? (
        <div className="messages-workspace-alert" role="alert">
          <TriangleAlert size={18} />
          <span>{workspaceError}</span>
          <button
            aria-label="Cerrar aviso"
            className="icon-btn"
            onClick={() => setWorkspaceError(null)}
            type="button"
          >
            <X size={17} />
          </button>
        </div>
      ) : null}
      <ConversationList
        activeId={activeId}
        conversations={conversations}
        filters={filters}
        hasMore={conversationHasMore}
        loading={loadingConversations}
        loadingMore={loadingMoreConversations}
        onFiltersChange={handleFiltersChange}
        onLoadMore={handleLoadMoreConversations}
        onRefresh={() => setRefreshNonce((current) => current + 1)}
        onSelect={handleSelectConversation}
        total={conversationTotal}
      />

      {activeConversation ? (
        <>
          <div className="messages-main">
            <ChatHeader
              conversation={activeConversation}
              onBack={handleBackToConversations}
              onCloseConversation={handleCloseConversation}
              onTakeConversation={handleTakeConversation}
              onToggleBot={handleToggleBot}
              onRockyModeChange={handleRockyModeChange}
            />

            <div className="chat-messages" onScroll={handleMessagesScroll} ref={messagesContainerRef}>
              {loadingOlderMessages ? <div className="messages-list-loader">Cargando mensajes antiguos...</div> : null}
              {!loadingOlderMessages && messageHasMore ? (
                <button className="messages-load-older" onClick={handleLoadOlderMessages} type="button">
                  Ver mensajes anteriores
                </button>
              ) : null}

              {loadingMessages && activeMessages.length === 0 ? (
                <div className="messages-list-loader">Cargando mensajes...</div>
              ) : (
                activeMessages.map((message) => (
                  <MessageBubble
                    key={message.id}
                    message={message}
                    onRetry={(failed) => {
                      const metadata = failed.metadata as Record<string, unknown> | null;
                      const selection = templateSelectionSchema.safeParse(metadata?.template);
                      void handleSendMessage(failed.content, failed.mediaUrl ?? undefined, failed.messageType, selection.success ? selection.data : undefined);
                    }}
                  />
                ))
              )}

              {!loadingMessages && activeMessages.length === 0 ? (
                <div className="empty-state compact">
                  <p>No hay mensajes para los filtros actuales.</p>
                </div>
              ) : null}

              <div ref={messagesEndRef} />
            </div>

            <div className="chat-count">{activeMessages.length} de {messageTotal} mensajes cargados</div>
            {activeConversation.rockySession?.mode === "COPILOT" && rockySuggestion ? (
              <div className="rocky-suggestion" role="status">
                <div><strong>Rocky sugiere</strong><p>{rockySuggestion.reply}</p></div>
                <div className="rocky-suggestion-actions">
                  <button className="btn btn-primary" type="button" onClick={async () => {
                    if (await handleSendMessage(rockySuggestion.reply)) setRockySuggestion(null);
                  }}>Enviar sugerencia</button>
                  <button className="btn btn-outline" type="button" onClick={() => setRockySuggestion(null)}>Descartar</button>
                </div>
              </div>
            ) : null}
            <MessageInput key={activeConversation.id} contact={activeConversation.contact} onSendMessage={handleSendMessage} />
          </div>

          <CustomerPanel conversation={activeConversation} />
        </>
      ) : (
        <div className="messages-main messages-empty-main">
          <div className="empty-state">
            <MessageCircle size={64} />
            <h2>Centro de Mensajes</h2>
            <p>Selecciona una conversación para comenzar a chatear</p>
          </div>
        </div>
      )}
    </div>
  );
}

