"use client";

import { useState, useRef, useEffect } from "react";
import { savePromoAction, deletePromoAction } from "@/app/admin/cupones/actions";
import { AlertTriangle } from "lucide-react";

export function PromoForm({ promo, promoters }: { promo?: any; promoters: any[] }) {
  const [loading, setLoading] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);

  return (
    <>
    <form action={async (formData) => {
      setLoading(true);
      try {
        await savePromoAction(formData);
      } catch (err: any) {
        if (err?.message === "NEXT_REDIRECT") throw err;
        alert(String(err));
        setLoading(false);
      }
    }} className="stack-lg">
      {promo && <input type="hidden" name="id" value={promo.id} />}
      
      <div className="form-grid">
        <label className="field">
          <span>Código del Cupón (Sin espacios, ej. LUIS10)</span>
          <input 
            type="text" 
            name="code" 
            required 
            defaultValue={promo?.code || ""} 
            style={{ textTransform: "uppercase" }}
            pattern="[A-Za-z0-9]+"
            title="Solo letras y números, sin espacios"
            placeholder="Ej. VIP2024"
          />
        </label>
      </div>

      <div className="form-grid" style={{ gridTemplateColumns: "1fr 1fr", gap: "24px 16px" }}>
        <label className="field">
          <span>Descuento para Cliente</span>
          <div style={{ display: "grid", gridTemplateColumns: "140px 1fr", gap: "8px" }}>
            <select name="discountType" defaultValue={promo?.discountType || "PERCENTAGE"}>
              <option value="PERCENTAGE">% Porcentaje</option>
              <option value="FIXED">S/ Fijo</option>
            </select>
            <input 
              type="number" 
              name="discountValue" 
              required 
              min="0" 
              step="0.01"
              placeholder="0.00" 
              defaultValue={promo?.discountValue || ""} 
              style={{ width: "100%" }}
            />
          </div>
        </label>

        <label className="field">
          <span>Mínimo de Compra (S/)</span>
          <input 
            type="number" 
            name="minOrderAmount" 
            min="0" 
            step="0.01" 
            placeholder="0.00"
            defaultValue={promo?.minOrderAmount || "0"} 
          />
          <p className="muted" style={{ fontSize: "12px", marginTop: "4px" }}>Requerido para proteger contra saldos negativos.</p>
        </label>
      </div>

      <div className="form-grid" style={{ gridTemplateColumns: "1fr 1fr", gap: "24px 16px" }}>
        <label className="field">
          <span>Comisión para el Promotor/Influencer</span>
          <div style={{ display: "grid", gridTemplateColumns: "140px 1fr", gap: "8px" }}>
            <select name="commissionType" defaultValue={promo?.commissionType || "FIXED"}>
              <option value="FIXED">S/ Fijo</option>
              <option value="PERCENTAGE">% Porcentaje</option>
            </select>
            <input 
              type="number" 
              name="commissionValue" 
              required 
              min="0" 
              step="0.01" 
              placeholder="0.00"
              defaultValue={promo?.commissionValue || ""} 
              style={{ width: "100%" }}
            />
          </div>
        </label>

        <label className="field">
          <span>Asignar a Promotor (Opcional)</span>
          <PromotorCombobox promoters={promoters} defaultValue={promo?.creatorId || ""} />
          <p className="muted" style={{ fontSize: "12px", marginTop: "4px" }}>Las comisiones se asociarán a este usuario.</p>
        </label>
      </div>

      <div style={{ marginTop: "12px" }}>
        <label style={{ display: "flex", flexDirection: "row", alignItems: "center", gap: "10px", cursor: "pointer", width: "fit-content" }}>
          <input 
            type="checkbox" 
            name="isActive" 
            id="isActive" 
            defaultChecked={promo ? promo.isActive : true} 
            style={{ width: "20px", height: "20px", cursor: "pointer", margin: 0 }}
          />
          <span style={{ cursor: "pointer", fontWeight: 600, fontSize: "0.95rem" }}>Cupón Activo</span>
        </label>
      </div>

      <div className="actions-row" style={{ marginTop: "32px", borderTop: "1px solid var(--border)", paddingTop: "24px" }}>
        <button type="submit" className="button button-primary" disabled={loading}>
          {loading ? "Guardando..." : "Guardar Cupón"}
        </button>
        {promo && (
          <button 
            type="button" 
            className="button button-ghost danger" 
            style={{ marginLeft: "auto" }}
            onClick={() => setShowConfirm(true)}
          >
            Eliminar
          </button>
        )}
      </div>
    </form>

    {showConfirm && (
      <div style={{ position: "fixed", inset: 0, background: "rgba(15, 23, 42, 0.6)", backdropFilter: "blur(4px)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100 }}>
        <div className="panel" style={{ width: "100%", maxWidth: "400px", padding: "24px", position: "relative", textAlign: "center", animation: "modalAppear 0.2s ease-out" }}>
          <div style={{ display: "flex", justifyContent: "center", marginBottom: "16px", color: "#ef4444" }}>
            <AlertTriangle size={48} strokeWidth={1.5} />
          </div>
          <h2 style={{ fontSize: "1.25rem", fontWeight: 600, color: "#0f172a", marginBottom: "8px" }}>
            Eliminar Cupón
          </h2>
          <p style={{ color: "#64748b", marginBottom: "24px", fontSize: "0.95rem" }}>
            ¿Estás seguro de que deseas eliminar este cupón de descuento? Esta acción no se puede deshacer.
          </p>
          <div style={{ display: "flex", gap: "12px", justifyContent: "center" }}>
            <button 
              type="button" 
              className="button button-outline" 
              onClick={() => setShowConfirm(false)}
              style={{ flex: 1 }}
            >
              Cancelar
            </button>
            <button 
              type="button" 
              className="button button-primary" 
              disabled={loading}
              onClick={async () => {
                setLoading(true);
                try {
                  await deletePromoAction(promo.id);
                } catch (err: any) {
                  if (err?.message === "NEXT_REDIRECT") throw err;
                  alert(String(err));
                  setLoading(false);
                }
              }}
              style={{ flex: 1, backgroundColor: "#ef4444", borderColor: "#ef4444" }}
            >
              {loading ? "Eliminando..." : "Sí, eliminar"}
            </button>
          </div>
        </div>
      </div>
    )}
    </>
  );
}


function PromotorCombobox({ promoters, defaultValue }: { promoters: any[], defaultValue: string }) {
  const [search, setSearch] = useState("");
  const [open, setOpen] = useState(false);
  const [selectedId, setSelectedId] = useState(defaultValue);
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const selectedPromotor = promoters.find((p: any) => p.id === selectedId);
  const filteredPromoters = promoters.filter((p: any) => 
    p.name.toLowerCase().includes(search.toLowerCase()) || 
    p.email.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div ref={wrapperRef} style={{ position: "relative", width: "100%" }}>
      <input type="hidden" name="creatorId" value={selectedId} />

      <div 
        onClick={() => setOpen(!open)}
        style={{
          padding: "8px 12px",
          border: "1px solid var(--border)",
          borderRadius: "8px",
          background: "#fff",
          cursor: "pointer",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center"
        }}
      >
        <span style={{ color: selectedId ? "inherit" : "#9ca3af" }}>
          {selectedId ? `${selectedPromotor?.name} (${selectedPromotor?.email})` : "-- Buscar y seleccionar promotor --"}
        </span>
        <span style={{ fontSize: "12px" }}>▼</span>
      </div>

      {open && (
        <div style={{
          position: "absolute", top: "100%", left: 0, right: 0,
          background: "#fff", border: "1px solid var(--border)",
          borderRadius: "8px", marginTop: "4px", zIndex: 50,
          boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1)",
          maxHeight: "250px", display: "flex", flexDirection: "column"
        }}>
          <div style={{ padding: "8px", borderBottom: "1px solid var(--border)" }}>
            <input
              type="text"
              placeholder="Buscar por nombre o correo..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              onClick={(e) => e.stopPropagation()}
              style={{ width: "100%", padding: "6px 10px", fontSize: "14px" }}
            />
          </div>
          <div style={{ overflowY: "auto", padding: "4px" }}>
            <div 
              onClick={() => { setSelectedId(""); setOpen(false); setSearch(""); }}
              style={{
                padding: "8px 12px", cursor: "pointer", borderRadius: "4px",
                background: selectedId === "" ? "#f3f4f6" : "transparent"
              }}
              onMouseEnter={(e: any) => (e.currentTarget.style.background = "#f9fafb")}
              onMouseLeave={(e: any) => (e.currentTarget.style.background = selectedId === "" ? "#f3f4f6" : "transparent")}
            >
              -- Sin asignar --
            </div>
            {filteredPromoters.length === 0 ? (
              <div style={{ padding: "8px 12px", color: "#6b7280", textAlign: "center" }}>No se encontraron usuarios</div>
            ) : (
              filteredPromoters.map((p: any) => (
                <div
                  key={p.id}
                  onClick={() => { setSelectedId(p.id); setOpen(false); setSearch(""); }}
                  style={{
                    padding: "8px 12px", cursor: "pointer", borderRadius: "4px",
                    background: selectedId === p.id ? "#f3f4f6" : "transparent"
                  }}
                  onMouseEnter={(e: any) => (e.currentTarget.style.background = "#f9fafb")}
                  onMouseLeave={(e: any) => (e.currentTarget.style.background = selectedId === p.id ? "#f3f4f6" : "transparent")}
                >
                  <div style={{ fontWeight: 500 }}>{p.name}</div>
                  <div style={{ fontSize: "12px", color: "#6b7280" }}>{p.email}</div>
                </div>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { QuoteStatus } from "@prisma/client";
import { User, Save, Send } from "lucide-react";
import { buildWhatsappHrefFromPhone } from "@/lib/utils";

type QuoteConversationPanelProps = {
  quoteId: string;
  initialStatus: QuoteStatus;
  initialAdminNotes: string | null;
  assignedToName: string | null;
  assignedToEmail: string | null;
  customerName: string;
  customerPhone: string;
  customerMessage: string | null;
  pdfLink?: string;
  quoteNumber?: string | null;
};

const statusMeta: Record<QuoteStatus, { label: string; style: React.CSSProperties }> = {
  PENDING: { label: "Nuevo", style: { background: "#fef3c7", color: "#b45309", border: "1px solid #fde68a" } },
  IN_REVIEW: { label: "En revisión", style: { background: "#e0e7ff", color: "#3730a3", border: "1px solid #c7d2fe" } },
  RESPONDED: { label: "Respondido", style: { background: "#dcfce7", color: "#166534", border: "1px solid #bbf7d0" } },
  CLOSED: { label: "Cerrado", style: { background: "#f3f4f6", color: "#4b5563", border: "1px solid #e5e7eb" } },
  ERP_REGISTERED: { label: "Registrada ERP", style: { background: "#dbeafe", color: "#1e40af", border: "1px solid #bfdbfe" } },
  ERROR: { label: "Con error", style: { background: "#fee2e2", color: "#b91c1c", border: "1px solid #fecaca" } },
};

export function QuoteConversationPanel({
  quoteId,
  initialStatus,
  initialAdminNotes,
  assignedToName,
  assignedToEmail,
  customerName,
  customerPhone,
  customerMessage,
  pdfLink,
  quoteNumber,
}: QuoteConversationPanelProps) {
  const [status, setStatus] = useState<QuoteStatus>(initialStatus);
  const [adminNotes, setAdminNotes] = useState(initialAdminNotes ?? "");
  const [isSavingNote, setIsSavingNote] = useState(false);
  const [isSavingStatus, setIsSavingStatus] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  // WhatsApp reply generation
  const [replyText, setReplyText] = useState(
    `Hola ${customerName}, te contacto sobre tu cotización ${quoteNumber || ""}. En respuesta a tu solicitud.${pdfLink ? `\n\nPuedes ver tu cotización en PDF aquí: ${pdfLink}` : ""}`
  );

  async function handleStatusChange(newStatus: QuoteStatus) {
    setIsSavingStatus(true);
    setSuccessMsg(null);
    try {
      const res = await fetch(`/api/admin/quotes/${quoteId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus }),
      });
      if (!res.ok) throw new Error("Failed to update status");
      setStatus(newStatus);
      showSuccess("Estado actualizado correctamente");
    } catch (err) {
      console.error(err);
      alert("Error al actualizar el estado");
    } finally {
      setIsSavingStatus(false);
    }
  }

  async function handleSaveNote() {
    setIsSavingNote(true);
    setSuccessMsg(null);
    try {
      const res = await fetch(`/api/admin/quotes/${quoteId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ adminNotes }),
      });
      if (!res.ok) throw new Error("Failed to save note");
      showSuccess("Nota guardada correctamente");
    } catch (err) {
      console.error(err);
      alert("Error al guardar la nota");
    } finally {
      setIsSavingNote(false);
    }
  }

  function showSuccess(msg: string) {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(null), 3000);
  }

  const currentMeta = statusMeta[status];
  const whatsappHref = buildWhatsappHrefFromPhone(customerPhone, replyText.trim());

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
      {/* Auto-Assignment Notification Panel at the Top */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "12px",
          padding: "12px 16px",
          background: "#eff6ff",
          border: "1px solid #bfdbfe",
          borderRadius: "10px",
        }}
      >
        <div style={{ width: "28px", height: "28px", borderRadius: "50%", background: "#dbeafe", color: "#1e40af", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "12px", fontWeight: "bold" }}>
          {assignedToName ? assignedToName.charAt(0).toUpperCase() : <User size={16} />}
        </div>
        <span style={{ fontSize: "14px", color: "#1e3a8a", fontWeight: "500" }}>
          Asesor a cargo:{" "}
          <strong style={{ fontWeight: "700" }}>
            {assignedToName ?? "Sin asignar"}
          </strong>
        </span>
      </div>

      {/* Status Editor Section */}
      <div className="panel" style={{ padding: "16px", display: "flex", flexDirection: "column", gap: "12px", background: "white" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <h3 style={{ fontSize: "14px", fontWeight: "700", color: "#0f172a", margin: 0 }}>Estado de la cotización</h3>
          <span style={{ ...currentMeta.style, padding: "4px 8px", borderRadius: "6px", fontSize: "12px", fontWeight: 600 }}>
            {currentMeta.label}
          </span>
        </div>

        <div style={{ display: "flex", gap: "8px", flexWrap: "wrap", marginTop: "8px" }}>
          {(Object.keys(statusMeta) as QuoteStatus[]).map((key) => {
            const meta = statusMeta[key];
            const isSelected = key === status;
            return (
              <button
                key={key}
                disabled={isSavingStatus}
                onClick={() => handleStatusChange(key)}
                style={{
                  ...meta.style,
                  cursor: "pointer",
                  padding: "6px 10px",
                  borderRadius: "6px",
                  fontSize: "12px",
                  fontWeight: 600,
                  transition: "all 0.15s ease",
                  opacity: isSavingStatus ? 0.6 : 1,
                  boxShadow: isSelected ? "0 0 0 2px #0f172a" : "none",
                }}
              >
                {meta.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* Chat Thread / Message History */}
      <div className="panel" style={{ padding: "16px", display: "flex", flexDirection: "column", gap: "16px", background: "#f8fafc" }}>
        <h3 style={{ fontSize: "14px", fontWeight: "700", color: "#0f172a", margin: 0 }}>Historial de Mensajes</h3>
        
        {/* Customer Bubble */}
        {customerMessage && (
          <div style={{ alignSelf: "flex-start", maxWidth: "85%", display: "flex", flexDirection: "column", gap: "4px" }}>
            <span style={{ fontSize: "11px", fontWeight: 600, color: "#64748b", marginLeft: "4px" }}>{customerName} (Cliente)</span>
            <div style={{ background: "white", padding: "10px 14px", borderRadius: "12px", borderTopLeftRadius: "0", border: "1px solid #e2e8f0", color: "#1e293b", fontSize: "14px", lineHeight: "1.5", boxShadow: "0 1px 2px rgba(0,0,0,0.05)" }}>
              {customerMessage}
            </div>
          </div>
        )}
        
        {/* Admin Notes Bubble */}
        <div style={{ alignSelf: "flex-end", maxWidth: "85%", display: "flex", flexDirection: "column", gap: "4px", marginTop: "8px", width: "100%" }}>
          <span style={{ fontSize: "11px", fontWeight: 600, color: "#166534", alignSelf: "flex-end", marginRight: "4px" }}>{assignedToName || "Administrador"} (Notas Internas)</span>
          <textarea
            value={adminNotes}
            onChange={(e) => setAdminNotes(e.target.value)}
            placeholder="Escribe notas de seguimiento interno aquí (ej. detalles de la llamada)..."
            style={{
              width: "100%",
              minHeight: "80px",
              padding: "10px 14px",
              borderRadius: "12px",
              borderTopRightRadius: "0",
              border: "1px solid #bbf7d0",
              background: "#dcfce7",
              color: "#14532d",
              fontSize: "13px",
              resize: "vertical",
              fontFamily: "inherit",
              boxShadow: "0 1px 2px rgba(0,0,0,0.05)"
            }}
          />
          <div style={{ display: "flex", justifyContent: "flex-end", gap: "8px", alignItems: "center", marginTop: "4px" }}>
            {successMsg && <span style={{ fontSize: "11px", color: "#16a34a", fontWeight: "600" }}>✓ {successMsg}</span>}
            <button
              onClick={handleSaveNote}
              disabled={isSavingNote}
              className="button button-primary"
              style={{ padding: "4px 12px", fontSize: "12px", borderRadius: "6px", height: "28px" }}
            >
              <Save size={14} style={{ marginRight: "4px" }} />
              {isSavingNote ? "Guardando..." : "Guardar nota"}
            </button>
          </div>
        </div>
      </div>

      {/* WhatsApp Reply Tools */}
      <div className="panel" style={{ padding: "16px", display: "flex", flexDirection: "column", gap: "12px", background: "white", borderTop: "3px solid #25D366" }}>
        <h3 style={{ fontSize: "14px", fontWeight: "700", color: "#0f172a", margin: 0, display: "flex", alignItems: "center", gap: "6px" }}>
          <Send size={16} style={{ color: "#25D366" }} /> Respuesta por WhatsApp
        </h3>
        <textarea
          value={replyText}
          onChange={(e) => setReplyText(e.target.value)}
          placeholder="Escribe tu respuesta para enviarla por WhatsApp..."
          style={{ width: "100%", minHeight: "100px", padding: "10px", borderRadius: "8px", border: "1px solid #cbd5e1", fontSize: "13px", resize: "vertical", fontFamily: "inherit" }}
        />
        {whatsappHref ? (
          <a
            href={whatsappHref}
            target="_blank"
            rel="noreferrer"
            className="button"
            style={{ alignSelf: "flex-end", background: "#25D366", color: "white", padding: "6px 16px", borderRadius: "6px", fontSize: "13px", fontWeight: 600, textDecoration: "none", display: "flex", alignItems: "center", gap: "6px" }}
          >
            <Send size={14} /> Enviar al cliente
          </a>
        ) : (
          <span style={{ fontSize: "12px", color: "#ef4444", alignSelf: "flex-end" }}>No hay teléfono válido para WhatsApp.</span>
        )}
      </div>

    </div>
  );
}

"use client";

import { useState } from "react";
import { FileText, Send } from "lucide-react";
import { buildWhatsappHrefFromPhone } from "@/lib/utils";

type QuoteCustomerMessageProps = {
  customerName: string;
  customerPhone: string;
  customerMessage: string;
  pdfLink?: string;
  quoteNumber?: string | null;
};

export function QuoteCustomerMessage({
  customerName,
  customerPhone,
  customerMessage,
  pdfLink,
  quoteNumber,
}: QuoteCustomerMessageProps) {
  const [replyText, setReplyText] = useState(
    `Hola ${customerName}, te contacto sobre tu cotización ${quoteNumber || ""}. En respuesta a tu mensaje: "${customerMessage}".${pdfLink ? `\n\nPuedes ver tu cotización en PDF aquí: ${pdfLink}` : ""}`
  );

  const whatsappHref = buildWhatsappHrefFromPhone(
    customerPhone,
    replyText.trim()
  );

  return (
    <div className="panel" style={{ padding: "20px", display: "flex", flexDirection: "column", gap: "12px", background: "#f8fafc", borderLeft: "4px solid #2563eb" }}>
      <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
        <FileText size={18} style={{ color: "#2563eb" }} />
        <h2 style={{ color: "#1e293b", fontSize: "15px", fontWeight: "700", margin: 0 }}>Mensaje del Cliente</h2>
      </div>
      <p style={{ color: "#334155", fontSize: "14px", lineHeight: "1.6", marginTop: "4px", fontStyle: "italic", background: "white", padding: "10px", borderRadius: "6px", border: "1px solid #e2e8f0" }}>
        "{customerMessage}"
      </p>

      <div style={{ marginTop: "8px", display: "flex", flexDirection: "column", gap: "8px" }}>
        <label style={{ fontSize: "13px", fontWeight: "600", color: "#475569" }}>Responder al cliente:</label>
        <textarea
          value={replyText}
          onChange={(e) => setReplyText(e.target.value)}
          placeholder="Escribe tu respuesta para enviarla por WhatsApp..."
          style={{
            width: "100%",
            minHeight: "160px",
            padding: "10px 12px",
            borderRadius: "8px",
            border: "1px solid #cbd5e1",
            fontSize: "13px",
            resize: "vertical",
            fontFamily: "inherit",
          }}
        />
        {whatsappHref ? (
          <a
            href={whatsappHref}
            target="_blank"
            rel="noreferrer"
            className="button button-primary"
            style={{
              display: "inline-flex",
              alignItems: "center",
              justifyContent: "center",
              gap: "8px",
              height: "36px",
              padding: "0 16px",
              fontSize: "13px",
              borderRadius: "8px",
              background: "#25D366", // WhatsApp green
              borderColor: "#25D366",
              color: "white",
              alignSelf: "flex-end",
              textDecoration: "none",
            }}
          >
            <Send size={14} />
            Enviar respuesta
          </a>
        ) : (
          <span style={{ fontSize: "12px", color: "#ef4444", alignSelf: "flex-end" }}>
            No hay teléfono válido para WhatsApp.
          </span>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useCallback } from "react";
import Script from "next/script";

declare global {
  interface Window {
    Culqi: any;
    culqi: () => void;
  }
}

type CulqiCheckoutProps = {
  publicKey: string;
  amount: number; // En céntimos
  currency: string;
  title: string;
  onToken: (token: string) => void;
  onError: (error: string) => void;
  isOpen: boolean;
  onClose: () => void;
};

export function CulqiCheckout({
  publicKey,
  amount,
  currency,
  title,
  onToken,
  onError,
  isOpen,
  onClose,
}: CulqiCheckoutProps) {
  const initCulqi = useCallback(() => {
    if (typeof window === "undefined" || !window.Culqi) return;
    
    window.Culqi.publicKey = publicKey;
    window.Culqi.settings({
      title: title,
      currency: currency,
      amount: amount,
    });
    window.Culqi.options({
      lang: "auto",
      modal: true,
      installments: false,
    });
    
    if (isOpen) {
      window.Culqi.open();
    }
  }, [publicKey, amount, currency, title, isOpen]);

  useEffect(() => {
    if (isOpen) {
      initCulqi();
    }
  }, [isOpen, initCulqi]);

  useEffect(() => {
    // Definir la función global que Culqi llama al terminar
    window.culqi = () => {
      if (window.Culqi.token) {
        const token = window.Culqi.token.id;
        onToken(token);
      } else if (window.Culqi.order) {
        // En caso de usar Yape o PagoEfectivo sin tarjeta directo
        const order = window.Culqi.order;
      } else {
        onError(window.Culqi.error?.user_message || "Error al procesar el pago");
      }
      onClose();
    };

    // Al cerrar el modal de Culqi
    const handleCulqiClose = setInterval(() => {
      if (isOpen && window.Culqi && !window.Culqi.isOpen) {
        onClose();
      }
    }, 500);

    return () => {
      clearInterval(handleCulqiClose);
    };
  }, [onToken, onError, onClose, isOpen]);

  return (
    <Script
      src="https://checkout.culqi.com/js/v4"
      strategy="afterInteractive"
      onLoad={() => {
        if (isOpen) initCulqi();
      }}
    />
  );
}

"use client";

import { useState, useEffect } from "react";
import {
  ArrowLeft,
  ShoppingCart,
  Play,
  FileText,
  ChevronDown,
  Plus,
  Minus,
  Check,
  Star,
  ExternalLink,
  MessageCircle,
  HelpCircle,
  Search
} from "lucide-react";
import { useCartStore, rehydrateCartStore } from "@/components/catalog/cart-store";
import { CartDrawer } from "@/components/catalog/cart-drawer";
import { StoreSideActions } from "@/components/catalog/store-side-actions";
import { formatCurrency } from "@/lib/utils";

type PublicFichaProduct = {
  id: string;
  name: string;
  code: string;
  unitLabel: string;
  unitPrice: number;
  wholesalePrice: number | null;
  wholesaleMinQty: number;
  boxPrice: number | null;
  unitsPerBox: number | null;
  stockUnits: number;
  imageUrl: string | null;
  slug: string;
  digitalProfile: {
    descriptionShort: string | null;
    descriptionFull: string | null;
    status: string;
  };
  specifications: { id: string; name: string; value: string }[];
  variants: { id: string; name: string; hexColor: string | null; imageUrl: string | null; sku: string | null; isAvailable: boolean }[];
  videos: { id: string; title: string; url: string; provider: string; videoId: string; thumbnailUrl: string | null }[];
  documents: { id: string; title: string; url: string; type: string }[];
};

type PublicFichaWorkspaceProps = {
  product: PublicFichaProduct;
  settings: any;
  quoteDefaults: any;
  isAdminView?: boolean;
};

export function PublicFichaWorkspace({
  product,
  settings,
  quoteDefaults,
  isAdminView = false,
}: PublicFichaWorkspaceProps) {
  const addItem = useCartStore((state) => state.addItem);

  // States
  const [selectedVariantIndex, setSelectedVariantIndex] = useState(0);
  const [quantity, setQuantity] = useState(1);
  const [isSpecsOpen, setIsSpecsOpen] = useState(false);
  const [activeVideoId, setActiveVideoId] = useState<string | null>(null);
  const [isZoomOpen, setIsZoomOpen] = useState(false);

  // Rehydrate cart on mount
  useEffect(() => {
    rehydrateCartStore();
  }, []);

  async function trackEvent(eventType: string) {
    if (isAdminView) return; // don't skew metrics with admin views
    try {
      await fetch("/api/p/analytics", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ productId: product.id, eventType }),
      });
    } catch (e) {
      console.error("Failed to track event:", e);
    }
  }

  const handleBack = () => {
    if (typeof window !== "undefined") {
      if (document.referrer && document.referrer.includes(window.location.host)) {
        window.history.back();
      } else {
        window.location.href = "/";
      }
    }
  };

  const selectedVariant = product.variants[selectedVariantIndex] || null;
  const currentImage = selectedVariant?.imageUrl || product.imageUrl;
  const currentSku = selectedVariant?.sku || product.code;

  const handleAddToCart = () => {
    // Map to the format needed by CartStore
    const productForCart: any = {
      id: product.id,
      code: currentSku,
      name: selectedVariant ? `${product.name} (${selectedVariant.name})` : product.name,
      unitLabel: product.unitLabel,
      unitPrice: product.unitPrice,
      wholesalePrice: product.wholesalePrice,
      wholesaleMinQty: product.wholesaleMinQty,
      boxPrice: product.boxPrice,
      unitsPerBox: product.unitsPerBox,
      stockUnits: product.stockUnits,
      imageUrl: currentImage,
      primaryMedia: currentImage ? {
        id: selectedVariant ? `variant-${selectedVariant.id}` : `base-${product.id}`,
        type: "IMAGE" as const,
        url: currentImage,
        altText: selectedVariant ? selectedVariant.name : product.name,
        sortOrder: 0
      } : null
    };

    const isWholesale = product.wholesalePrice && quantity >= product.wholesaleMinQty;
    const mode = isWholesale ? "wholesale" : "unit";

    addItem(productForCart, mode as any, quantity);
    
    // Dispatch event to open CartDrawer
    window.dispatchEvent(new CustomEvent("store-cart:open"));
    
    trackEvent("ADD_TO_CART_FROM_QR");
  };

  const handlePlayVideo = (videoId: string) => {
    setActiveVideoId(videoId);
    trackEvent("VIDEO_PLAY");
  };

  const handleOpenDoc = (url: string) => {
    trackEvent("DOCUMENT_OPEN");
    window.open(url, "_blank");
  };

  const incrementQty = () => {
    if (quantity < product.stockUnits) {
      setQuantity((prev) => prev + 1);
    }
  };

  const decrementQty = () => {
    if (quantity > 1) {
      setQuantity((prev) => prev - 1);
    }
  };

  const effectivePrice = product.wholesalePrice && quantity >= product.wholesaleMinQty
    ? Number(product.wholesalePrice)
    : Number(product.unitPrice);

  return (
    <div style={{ background: "#f8fafc", minHeight: "100vh", paddingBottom: "80px" }}>
      {/* Admin view alert banner */}
      {isAdminView && (
        <div style={{ background: "#ef4444", color: "white", padding: "8px 16px", textTransform: "uppercase", fontSize: "11px", fontWeight: "800", letterSpacing: "0.05em", textAlign: "center", position: "sticky", top: 0, zIndex: 100 }}>
          Vista Previa de Administrador (Borrador)
        </div>
      )}

      {/* Header */}
      <header style={{ background: "white", borderBottom: "1px solid #e2e8f0", padding: "12px 16px", display: "flex", justifyContent: "space-between", alignItems: "center", position: "sticky", top: isAdminView ? "30px" : 0, zIndex: 50 }}>
        <button
          onClick={handleBack}
          style={{ background: "none", border: "none", color: "#334155", display: "flex", alignItems: "center", gap: "6px", cursor: "pointer", fontSize: "14px", fontWeight: "600", padding: "4px 0" }}
        >
          <ArrowLeft size={18} />
          Volver
        </button>
        
        <span style={{ fontWeight: "800", fontSize: "14px", color: "#2320DA", letterSpacing: "0.05em" }}>
          IMPORTADORA SUPER
        </span>

        <button
          onClick={() => window.dispatchEvent(new CustomEvent("store-cart:open"))}
          style={{ background: "none", border: "none", cursor: "pointer", position: "relative", padding: "6px" }}
        >
          <ShoppingCart size={20} style={{ color: "#334155" }} />
        </button>
      </header>

      {/* Main Content Container */}
      <main style={{ maxWidth: "480px", margin: "0 auto", padding: "16px" }} className="stack-md">
        
        {/* Product Card with Hero Image */}
        <section className="panel" style={{ background: "white", borderRadius: "16px", border: "1px solid #e2e8f0", padding: "16px", display: "flex", flexDirection: "column", gap: "16px" }}>
          <div style={{ position: "relative", height: "280px", display: "flex", alignItems: "center", justifyContent: "center", background: "#f8fafc", borderRadius: "12px", border: "1px solid #f1f5f9" }}>
            {currentImage ? (
              <>
                <img
                  src={currentImage}
                  alt={product.name}
                  style={{ maxWidth: "90%", maxHeight: "90%", objectFit: "contain", cursor: "pointer" }}
                  onClick={() => setIsZoomOpen(true)}
                />
                <button
                  type="button"
                  onClick={() => setIsZoomOpen(true)}
                  style={{
                    position: "absolute",
                    bottom: "12px",
                    right: "12px",
                    background: "white",
                    border: "1px solid #cbd5e1",
                    borderRadius: "50%",
                    width: "36px",
                    height: "36px",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    boxShadow: "0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1)",
                    cursor: "pointer",
                    color: "#475569"
                  }}
                  title="Ver en pantalla completa"
                >
                  <Search size={18} />
                </button>
              </>
            ) : (
              <div style={{ color: "#94a3b8", fontSize: "14px" }}>Sin imagen disponible</div>
            )}
          </div>

          <div className="stack-xxs">
            <h1 style={{ fontSize: "20px", fontWeight: "800", color: "#0f172a", lineHeight: "1.3" }}>
              {product.name}
              {selectedVariant ? ` (${selectedVariant.name})` : ""}
            </h1>
            
            {product.digitalProfile.descriptionShort && (
              <p style={{ fontSize: "14px", color: "#475569", fontStyle: "italic", margin: "6px 0 0" }}>
                "{product.digitalProfile.descriptionShort}"
              </p>
            )}

            <div style={{ display: "flex", gap: "8px", flexWrap: "wrap", marginTop: "12px" }}>
              <span style={{ background: "#f1f5f9", fontSize: "12px", padding: "4px 8px", borderRadius: "6px", color: "#475569", fontWeight: "500" }}>
                SKU: {currentSku}
              </span>
              <span style={{ background: "#fffbeb", fontSize: "12px", padding: "4px 8px", borderRadius: "6px", color: "#b45309", fontWeight: "600", display: "flex", alignItems: "center", gap: "4px" }}>
                <Star size={14} fill="#b45309" />
                4.9 (Valoración de tienda)
              </span>
            </div>
          </div>
        </section>

        {/* Dynamic Price Tiers */}
        <section className="panel stack-sm" style={{ background: "white", borderRadius: "16px", border: "1px solid #e2e8f0", padding: "16px" }}>
          <h2 style={{ fontSize: "13px", fontWeight: "800", color: "#64748b", textTransform: "uppercase", letterSpacing: "0.05em", margin: 0 }}>Precios y Escalas</h2>
          
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
            <div style={{ background: "#f8fafc", padding: "12px", borderRadius: "10px", border: "1px solid #f1f5f9" }}>
              <p style={{ fontSize: "11px", color: "#64748b", margin: "0 0 4px" }}>Por Unidad</p>
              <p style={{ fontSize: "20px", fontWeight: "800", color: "#0f172a", margin: 0 }}>
                {formatCurrency(product.unitPrice)}
