  customerPhone: string | null;
  sheetNumber: string;
};

/**
 * Normaliza el teléfono para enlaces de WhatsApp agregando prefijo de Perú (51) si es de 9 dígitos.
 */
export function normalizeComplaintPhone(phone: string | null | undefined) {
  if (!phone) {
    return null;
  }

  const digits = phone.replace(/\D/g, "");

  if (!digits) {
    return null;
  }

  if (digits.startsWith("51")) {
    return digits;
  }

  if (digits.length === 9) {
    return `51${digits}`;
  }

  return digits;
}

/**
 * Genera el siguiente número de hoja correlativo anual de forma segura
 */
export async function generateNextSheetNumber(year: number): Promise<{
  sheetNumber: string;
  serialNumber: number;
}> {
  // Bucle de reintento simple para mitigar condiciones de carrera concurrentes
  let attempts = 0;
  const maxAttempts = 5;

  while (attempts < maxAttempts) {
    try {
      const latestComplaint = await prisma.complaint.findFirst({
        where: { year },
        orderBy: { serialNumber: "desc" },
        select: { serialNumber: true },
      });

      const nextSerial = (latestComplaint?.serialNumber ?? 0) + 1;
      const sheetNumber = `LR-${year}-${String(nextSerial).padStart(6, "0")}`;

      return {
        sheetNumber,
        serialNumber: nextSerial,
      };
    } catch (error) {
      attempts += 1;
      if (attempts >= maxAttempts) {
        throw error;
      }
      // Pequeña espera asíncrona antes de reintentar
      await new Promise((resolve) => setTimeout(resolve, 50 * attempts));
    }
  }

  throw new Error("No se pudo generar un número correlativo único.");
}

/**
 * Redacta el cuerpo de respuesta en texto plano
 */
export function buildComplaintResponseText(input: {
  sheetNumber: string;
  customerName: string;
  type: string;
  reason: string;
  responseText: string;
}) {
  const lines = [
    `Hola ${input.customerName},`,
    "",
    `Hemos registrado la respuesta formal para tu ${input.type.toLowerCase()} con código ${input.sheetNumber}.`,
    `Detalle del motivo: ${input.reason}`,
    "",
    input.responseText.trim(),
    "",
    "Saludos cordiales,",
    "ORIGINAL J J S.A.C.",
  ];

  return lines.join("\n");
}

/**
 * Genera un enlace mailto para responder por correo
 */
export function buildComplaintEmailHref(
  contact: ComplaintContact,
  responseText: string,
  type: string,
  reason: string,
) {
  if (!contact.customerEmail) {
    return null;
  }

  const body = buildComplaintResponseText({
    sheetNumber: contact.sheetNumber,
    customerName: contact.customerName,
    type,
    reason,
    responseText,
  });

  const params = new URLSearchParams({
    subject: `Respuesta a tu ${type} en Libro de Reclamaciones - ${contact.sheetNumber}`,
    body,
  });

  return `mailto:${contact.customerEmail}?${params.toString()}`;
}

/**
 * Genera un enlace de WhatsApp para enviar la respuesta
 */
export function buildComplaintWhatsappHref(
  contact: ComplaintContact,
  responseText: string,
  type: string,
  reason: string,
) {
  const phone = normalizeComplaintPhone(contact.customerPhone);

  if (!phone) {
    return null;
  }

  const message = buildComplaintResponseText({
    sheetNumber: contact.sheetNumber,
    customerName: contact.customerName,
    type,
    reason,
    responseText,
  });

  return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
}

import fs from "fs";
import path from "path";

export async function downloadAndSaveQuotePdf(externalId: string, quoteNumber: string): Promise<string | null> {
  try {
    const apiUrl = process.env.FACTURADOR_API_URL?.trim();
    if (!apiUrl) {
      console.warn("[PDF Sync] FACTURADOR_API_URL is not set.");
      return null;
    }
    
    // Derived domain: replace /api/v1 or /api or similar at the end
    let domain = apiUrl.replace(/\/api\/v1\/?$/, "").replace(/\/api\/?$/, "");
    
    // The print URL
    const pdfUrl = `${domain}/print/quotation/${externalId}/a4`;
    
    console.log(`[PDF Sync] Downloading PDF from: ${pdfUrl}`);
    
    const response = await fetch(pdfUrl, {
      headers: {
        "Authorization": `Bearer ${process.env.FACTURADOR_API_TOKEN}`
      }
    });
    
    if (!response.ok) {
      console.warn(`[PDF Sync] Failed to download PDF from ERP. Status: ${response.status}`);
      return null;
    }
    
    const buffer = Buffer.from(await response.arrayBuffer());
    
    // Target directory inside the project uploads path
    const uploadDir = path.join(process.cwd(), "public", "uploads", "quotations");
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true });
    }
    
    // Sanitized file name
    const fileName = `${quoteNumber.replace(/[^a-zA-Z0-9-_]/g, "_")}.pdf`;
    const filePath = path.join(uploadDir, fileName);
    
    fs.writeFileSync(filePath, buffer);
    console.log(`[PDF Sync] Saved PDF successfully to: ${filePath}`);
    
    return `/uploads/quotations/${fileName}`;
  } catch (error) {
    console.error("[PDF Sync] Error downloading or saving quote PDF:", error);
    return null;
  }
}

